/* Element Selector */
h1 {
    color: #FF6A2A;
    font-family: sans-serif;
}

/* Class Selector */
.card {
    background-color: #252422;
    color: #FFFFFF;
}

/* ID Selector */
#main-header {
    border-bottom: 2px solid #4A4A4A;
}

* {
    box-sizing: border-box;
}

.box {
    width: 350px;
    padding: 24px;
    border: 1px solid #4A4A4A;
    margin: 16px auto;
    background-color: #1B1B1B;
}

.hero-banner {
    background: linear-gradient(135deg, #FF6A2A 0%, #FF8C42 100%);
    color: rgba(255, 255, 255, 0.95);
    padding: 48px;
    border-radius: 8px;
}

body {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 1rem;
    line-height: 1.6;
    color: #CFCFCF;
}

h1 {
    font-size: 2.5rem;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #FFFFFF;
}

.nav-menu {
    list-style: none;
    padding: 0;
}

.nav-item {
    display: inline-block;
    margin-right: 16px;
}

.nav-item a {
    display: block;
    padding: 8px 16px;
    text-decoration: none;
    color: #FFFFFF;
}

.navbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16px 32px;
    background-color: #252422;
    border-bottom: 1px solid #4A4A4A;
}

.nav-links {
    display: flex;
    gap: 24px;
    align-items: center;
}

.card-row {
    display: flex;
    flex-wrap: wrap;
    gap: 20px;
}

.card-item {
    flex: 1 1 280px;
    background-color: #252422;
    padding: 24px;
    border: 1px solid #4A4A4A;
}

.grid-container {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
}

.grid-card {
    background-color: #252422;
    padding: 20px;
    border: 1px solid #4A4A4A;
}

.gallery {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 16px;
}

.gallery-item {
    width: 100%;
    height: 200px;
    object-fit: cover;
}

.sticky-header {
    position: sticky;
    top: 0;
    z-index: 100;
    background-color: #1B1B1B;
}

.product-card {
    position: relative;
    padding: 24px;
    background-color: #252422;
}

.badge {
    position: absolute;
    top: 12px;
    right: 12px;
    background-color: #FF6A2A;
    color: white;
    padding: 4px 8px;
    font-size: 0.75rem;
}

.btn {
    background-color: #FF6A2A;
    color: #FFFFFF;
    padding: 12px 24px;
    border: none;
    transition: background-color 0.2s ease;
}

.btn:hover {
    background-color: #FF8C42;
}

.btn:focus-visible {
    outline: 2px solid #35C759;
    outline-offset: 2px;
}

.custom-list li {
    position: relative;
    padding-left: 20px;
    list-style: none;
}

.custom-list li::before {
    content: "•";
    position: absolute;
    left: 0;
    color: #FF6A2A;
}

:root {
    --bg-primary: #FFFFFF;
    --text-primary: #1B1B1B;
    --accent-color: #FF6A2A;
}

[data-theme="dark"] {
    --bg-primary: #1B1B1B;
    --text-primary: #FFFFFF;
    --accent-color: #FF8C42;
}

body {
    background-color: var(--bg-primary);
    color: var(--text-primary);
}

.container {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

@media (min-width: 768px) {
    .container {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 24px;
    }
}

.interactive-card {
    background-color: #252422;
    border: 1px solid #4A4A4A;
    padding: 24px;
    transition: transform 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease;
}

.interactive-card:hover {
    transform: translateY(-6px);
    border-color: #FF6A2A;
    box-shadow: 0 12px 24px rgba(255, 106, 42, 0.2);
}

.card-container {
    perspective: 1000px;
}

.card-inner {
    width: 300px;
    height: 400px;
    position: relative;
    transition: transform 0.8s;
    transform-style: preserve-3d;
}

.card-container:hover .card-inner {
    transform: rotateY(180deg);
}

@keyframes spin {
    from {
        transform: rotate(0deg);
    }
    to {
        transform: rotate(360deg);
    }
}

.spinner {
    width: 32px;
    height: 32px;
    border: 3px solid #4A4A4A;
    border-top-color: #FF6A2A;
    border-radius: 50%;
    animation: spin 1s linear infinite;
}

.glass-card {
    background: rgba(37, 36, 34, 0.6);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
    border-radius: 12px;
    padding: 32px;
}

::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

::-webkit-scrollbar-track {
    background: #1B1B1B;
}

::-webkit-scrollbar-thumb {
    background: #4A4A4A;
    border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
    background: #FF6A2A;
}

::selection {
    background-color: #FF6A2A;
    color: #FFFFFF;
}

.card-wrapper {
    container-type: inline-size;
    container-name: cardContainer;
}

.card-content {
    display: flex;
    flex-direction: column;
}

@container cardContainer (min-width: 400px) {
    .card-content {
        flex-direction: row;
        align-items: center;
    }
}

:root {
    --bg: #1B1B1B;
    --card-bg: #252422;
    --accent: #FF6A2A;
    --text: #CFCFCF;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    background-color: var(--bg);
    color: var(--text);
    font-family: system-ui, sans-serif;
    line-height: 1.6;
}

.navbar {
    position: sticky;
    top: 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16px 32px;
    background: rgba(27, 27, 27, 0.9);
    backdrop-filter: blur(8px);
    border-bottom: 1px solid #4A4A4A;
}

.hero {
    padding: 80px 32px;
    text-align: center;
}

.hero h1 {
    color: #FFFFFF;
    font-size: 3rem;
    margin-bottom: 16px;
}

.grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 24px;
    padding: 32px;
}

.card {
    background: var(--card-bg);
    padding: 24px;
    border: 1px solid #4A4A4A;
    transition: transform 0.3s ease;
}

.card:hover {
    transform: translateY(-4px);
    border-color: var(--accent);
}
